import test from 'node:test';
import assert from 'node:assert/strict';
import { loadConfig } from '../scripts/config.mjs';
import { scrapeWatchSearches, isGithubReliabilityMention } from '../scripts/search.mjs';
import { filterAndClassify } from '../scripts/filter.mjs';
import { diffSeen, markSeen } from '../scripts/store.mjs';
import { buildTweetMessage, postToSlack } from '../scripts/notify-slack.mjs';
import { planAnnouncements } from '../scripts/chain.mjs';
import { buildPrompt } from '../scripts/classify.mjs';

const config = loadConfig({
  BROWSERBASE_API_KEY: 'test', BROWSERBASE_PROJECT_ID: 'test',
  X_AUTH_TOKEN: 'test', X_CSRF_TOKEN: 'test', SLACK_WEBHOOK_URL: 'https://example.test/webhook',
});
const raw = (id, text) => ({
  id, text, author: 'dev', url: `https://x.com/dev/status/${id}`,
  createdAt: '2026-10-27T06:00:00Z', conversationId: 'thread',
});

test('GitHub results must discuss reliability in their own text, not merely link to GitHub', () => {
  assert.equal(isGithubReliabilityMention(raw('1', 'Github outage again')), true);
  assert.equal(isGithubReliabilityMention(raw('2', 'Is GITHUB down?')), true);
  assert.equal(isGithubReliabilityMention(raw('3', 'Github reliability has improved')), true);
  assert.equal(isGithubReliabilityMention(raw('4', 'Zero downtime deployments https://t.co/code')), false);
  assert.equal(isGithubReliabilityMention(raw('5', 'https://t.co/repo')), false);
});

test('GitHub query defaults cover outages and reliability, with a separate override', () => {
  assert.match(config.githubSearchQuery, /github/);
  for (const term of ['outage', 'downtime', 'reliability', 'degraded']) {
    assert.ok(config.githubSearchQuery.includes(term));
  }
  const overridden = loadConfig({
    BROWSERBASE_API_KEY: 'test', BROWSERBASE_PROJECT_ID: 'test', X_AUTH_TOKEN: 'test',
    X_CSRF_TOKEN: 'test', SLACK_WEBHOOK_URL: 'test', X_GITHUB_SEARCH_QUERY: 'github outage',
  });
  assert.equal(overridden.githubSearchQuery, 'github outage');
  assert.equal(overridden.searchQuery, config.searchQuery);
});

test('separate searches deliver GitHub tweets once with accurate labels and retry on Slack failure', async () => {
  const calls = [];
  const result = await scrapeWatchSearches(config, { scrape: async (c) => {
    calls.push(c);
    return { source: 'json', loginWall: false, tweets: c.searchQuery === config.searchQuery
      ? [raw('1', '@entirehq great'), raw('2', '@entirehq github outage')]
      : [raw('2', '@entirehq github outage'), raw('3', 'GitHub is down again')] };
  } });
  assert.equal(calls.length, 2);
  assert.deepEqual(calls.map((c) => new URL(c.searchUrl).searchParams.get('q')),
    [config.searchQuery, config.githubSearchQuery]);
  const store = { seen: ['1'], baselined: true };
  const { fresh } = diffSeen(store, filterAndClassify(result.tweets, config));
  assert.deepEqual(fresh.map((t) => t.id), ['2', '3']);
  const github = fresh.find((t) => t.id === '3');
  assert.equal(github.matchedVia, 'github');
  assert.match(buildPrompt(github), /Matched: GitHub outage\/reliability search/);
  const payload = buildTweetMessage(github, { tier: 'routine' });
  assert.match(payload.text, /discussed GitHub reliability/);
  assert.match(JSON.stringify(payload.blocks), /GitHub reliability/);
  assert.doesNotMatch(JSON.stringify(payload), /mentioned @entirehq/);
  const failed = await postToSlack(config.slackWebhookUrl, payload, {
    fetchImpl: async () => ({ ok: false, status: 503 }), retryDelayMs: 0,
  });
  assert.equal(failed.ok, false);
  assert.equal(diffSeen(store, [github]).fresh.length, 1);
  const delivered = await postToSlack(config.slackWebhookUrl, payload, {
    fetchImpl: async () => ({ ok: true, status: 200 }),
  });
  assert.equal(delivered.ok, true);
  assert.equal(diffSeen(markSeen(store, github.id), [github]).fresh.length, 0);
});

test('GitHub tweets keep their individual Slack posts even when a thread budget is exhausted', () => {
  const tweets = filterAndClassify([raw('1', 'github down'), raw('2', 'github unreliable')]
    .map((t) => ({ ...t, searchTopic: 'github' })), config);
  const plan = planAnnouncements(tweets.map((tweet) => ({ tweet, decision: { tier: 'routine' } })), { limit: 0 });
  assert.deepEqual(plan.map((p) => p.type), ['post', 'post']);
});

test('login walls on either search are surfaced', async () => {
  const result = await scrapeWatchSearches(config, { scrape: async (c) => ({
    source: 'dom', tweets: [], loginWall: c.searchQuery === config.githubSearchQuery,
  }) });
  assert.equal(result.loginWall, true);
});

test('failed searches identify the affected monitor and do not look like empty results', async () => {
  await assert.rejects(scrapeWatchSearches(config, { scrape: async (c) => {
    if (c.searchQuery === config.githubSearchQuery) throw new Error('quota exceeded');
    return { source: 'json', tweets: [], loginWall: false };
  } }), /GitHub reliability search failed: quota exceeded/);
});
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { filterAndClassify, MATCH_HANDLE, MATCH_LINK, MATCH_BOTH } from '../scripts/filter.mjs';

const BRAND = { ownHandle: 'entirehq', brandDomain: 'entire.io' };

function raw(overrides) {
  return {
    id: '1',
    author: 'somedev',
    text: 'hi @entirehq',
    url: 'https://x.com/somedev/status/1',
    createdAt: '2026-08-18T14:00:00.000Z',
    inReplyToStatusId: null,
    isQuoteStatus: false,
    ...overrides,
  };
}

test('filterAndClassify labels a plain mention', () => {
  const [t] = filterAndClassify([raw({})], BRAND);
  assert.equal(t.kind, 'mention');
});

test('filterAndClassify labels a reply', () => {
  const [t] = filterAndClassify([raw({ inReplyToStatusId: '999' })], BRAND);
  assert.equal(t.kind, 'reply');
});

test('filterAndClassify labels a reply found via the DOM sentinel', () => {
  const [t] = filterAndClassify([raw({ inReplyToStatusId: 'unknown' })], BRAND);
  assert.equal(t.kind, 'reply');
});

test('filterAndClassify labels a quote tweet', () => {
  const [t] = filterAndClassify([raw({ isQuoteStatus: true })], BRAND);
  assert.equal(t.kind, 'quote');
});

test('reply wins over quote when a tweet is both', () => {
  const [t] = filterAndClassify(
    [raw({ isQuoteStatus: true, inReplyToStatusId: '999' })],
    BRAND,
  );
  assert.equal(t.kind, 'reply');
});

test('filterAndClassify drops posts authored by the watched account', () => {
  const tweets = filterAndClassify(
    [raw({ id: '1', author: 'entirehq' }), raw({ id: '2', author: 'somedev' })],
    BRAND,
  );
  assert.deepEqual(tweets.map((t) => t.id), ['2']);
});

test('own-post matching ignores case and a leading @', () => {
  const tweets = filterAndClassify([raw({ author: 'EntireHQ' })], { ...BRAND, ownHandle: '@entirehq' });
  assert.deepEqual(tweets, []);
});

test('filterAndClassify emits exactly the Tweet fields, no raw leftovers', () => {
  const [t] = filterAndClassify([raw({ inReplyToStatusId: '999' })], BRAND);
  assert.deepEqual(Object.keys(t).sort(), [
    'author', 'conversationId', 'createdAt', 'followers', 'followsUs', 'id', 'kind', 'matchedVia',
    'text', 'url', 'verified',
  ]);
});

test('filterAndClassify sorts oldest first', () => {
  const tweets = filterAndClassify(
    [
      raw({ id: 'new', createdAt: '2026-08-18T16:00:00.000Z' }),
      raw({ id: 'old', createdAt: '2026-08-18T09:00:00.000Z' }),
    ],
    BRAND,
  );
  assert.deepEqual(tweets.map((t) => t.id), ['old', 'new']);
});

test('filterAndClassify drops an entry missing text', () => {
  const tweets = filterAndClassify([raw({ text: undefined })], BRAND);
  assert.deepEqual(tweets, []);
});

test('filterAndClassify drops an entry missing url', () => {
  const tweets = filterAndClassify([raw({ url: undefined })], BRAND);
  assert.deepEqual(tweets, []);
});

test('filterAndClassify drops an entry missing url (empty string)', () => {
  const tweets = filterAndClassify([raw({ url: '' })], BRAND);
  assert.deepEqual(tweets, []);
});

test('filterAndClassify drops an entry with unparseable createdAt', () => {
  const tweets = filterAndClassify([raw({ createdAt: 'not a date' })], BRAND);
  assert.deepEqual(tweets, []);
});

test('filterAndClassify keeps an entry with empty text', () => {
  const [t] = filterAndClassify([raw({ text: '' })], BRAND);
  assert.equal(t.text, '');
});

test('filterAndClassify tolerates junk input', () => {
  assert.deepEqual(filterAndClassify(null, BRAND), []);
  assert.deepEqual(filterAndClassify([null, 'nope'], BRAND), []);
});

test('a post that tags the account matched on the handle', () => {
  const [t] = filterAndClassify([raw({ text: 'hi @EntireHQ' })], BRAND);
  assert.equal(t.matchedVia, MATCH_HANDLE);
});

test('a post whose only link is the site matched on the link', () => {
  const [t] = filterAndClassify(
    [raw({ text: 'this is the git host I switched to https://t.co/abc', links: ['https://entire.io/blog/post'] })],
    BRAND,
  );
  assert.equal(t.matchedVia, MATCH_LINK);
});

test('the domain written out in the text counts as a link match', () => {
  const [t] = filterAndClassify([raw({ text: 'go read entire.io, seriously' })], BRAND);
  assert.equal(t.matchedVia, MATCH_LINK);
});

test('a post that does both is recorded as both', () => {
  const [t] = filterAndClassify(
    [raw({ text: '@entirehq shipped this https://t.co/abc', links: ['entire.io/changelog'] })],
    BRAND,
  );
  assert.equal(t.matchedVia, MATCH_BOTH);
});

test('an unrelated link is not a site match', () => {
  const [t] = filterAndClassify(
    [raw({ text: 'hi @entirehq', links: ['https://github.com/entire/io'] })],
    BRAND,
  );
  assert.equal(t.matchedVia, MATCH_HANDLE);
});

test('a result that shows neither signal is attributed to the handle', () => {
  // The DOM path drops the leading "Replying to @entirehq" from the body, so
  // a real handle match can arrive with no visible evidence. Calling that a
  // link match would put "linked entire.io" on a post with no link in it.
  const [t] = filterAndClassify([raw({ text: 'yes exactly', inReplyToStatusId: 'unknown' })], BRAND);
  assert.equal(t.matchedVia, MATCH_HANDLE);
});

test('match attribution survives a missing brand domain', () => {
  const [t] = filterAndClassify([raw({ links: ['entire.io/x'] })], { ownHandle: 'entirehq' });
  assert.equal(t.matchedVia, MATCH_HANDLE);
});

test('filterAndClassify carries the thread id through, and null when there is none', () => {
  const [threaded] = filterAndClassify([raw({ conversationId: '777' })], BRAND);
  assert.equal(threaded.conversationId, '777');
  const [loose] = filterAndClassify([raw({})], BRAND);
  assert.equal(loose.conversationId, null);
});
// One live scrape, printed, notifying nobody. This is the manual gate before
// the watcher is considered working.
import { loadConfig, loadEnvFile, getProjectDir, ConfigError } from './config.mjs';
import { filterAndClassify } from './filter.mjs';
import { formatTweet, printWarning, printQuiet } from './notify-terminal.mjs';
import { scrapeWatchSearches } from './search.mjs';

loadEnvFile(getProjectDir());

let config;
try {
  config = loadConfig();
} catch (err) {
  console.error(err instanceof ConfigError ? err.message : err);
  process.exit(1);
}

console.log(`Dry run — scraping ${config.searchUrl}`);
console.log(`GitHub reliability query: ${config.githubSearchQuery}`);
console.log('Nothing will be sent to Slack.\n');

try {
  const { source, tweets, loginWall } = await scrapeWatchSearches(config);
  printQuiet(`extraction path: ${source}`);

  if (loginWall) {
    printWarning('X served a login wall — X_AUTH_TOKEN / X_CSRF_TOKEN are stale. Re-copy both cookies.');
    process.exit(1);
  }

  const classified = filterAndClassify(tweets, config);
  printQuiet(`${tweets.length} tweets scraped, ${classified.length} after filtering out @${config.ownHandle}`);
  const byLink = classified.filter((t) => ['link', 'both'].includes(t.matchedVia)).length;
  printQuiet(`${byLink} of them matched on a ${config.brandDomain} link`);

  if (classified.length === 0) {
    printWarning('No tweets found. Either the search is genuinely empty or extraction broke.');
    process.exit(1);
  }

  console.log('');
  for (const tweet of classified) console.log(formatTweet(tweet));
  console.log(`\nLooks healthy. ${classified.length} tweets would be tracked.`);
} catch (err) {
  printWarning(`scrape failed: ${err.message}`);
  process.exit(1);
}
