     3	export function isGithubReliabilityMention(tweet) {
     4	  const text = String(tweet.text || '');
     5	  return /github/i.test(text) && /\b(outages?|down|downtime|reliability|unreliable|unavailable|degraded)\b/i.test(text);
     6	}
     7	
     8	export async function scrapeWatchSearches(config, { scrape = scrapeSearch } = {}) {
     9	  const queries = [
    10	    { name: 'Entire', query: config.searchQuery },
    11	    { name: 'GitHub reliability', query: config.githubSearchQuery },
    12	  ];
    13	  const results = await Promise.all(queries.map(async ({ name, query }) => {
    14	    try {
