    16	        ...config,
    17	        searchQuery: query,
    18	        searchUrl: `https://x.com/search?q=${encodeURIComponent(query)}&src=typed_query&f=live`,
    19	      });
    20	      return { ...result, name, query };
    21	    } catch (err) {
    22	      throw new Error(`${name} search failed: ${err.message}`, { cause: err });
    23	    }
    24	  }));
    25	
    26	  return {
    27	    source: results.map((r) => `${r.name}:${r.source}`).join(', '),
