    29	    tweets: results.flatMap((r) => r.tweets
    30	      .filter((tweet) => r.name !== 'GitHub reliability' || isGithubReliabilityMention(tweet))
    31	      .map((tweet) => ({
    32	        ...tweet,
    33	        searchTopic: r.name === 'GitHub reliability' ? 'github' : null,
