+      retryable = false;
+      return { ...parseGithubStatus(body), checkedAt: new Date().toISOString() };
+    } catch (error) {
+      if (retryable && attempt < maxAttempts) {
+        await sleep(500 * 2 ** (attempt - 1));
+        continue;
